(6975056, 1052201, 114285, '<td valign="top"><img alt="'' . substr(''//webpages.charter.net/yospiff/Images/Smileys/WooHoo2.gif'', strrpos(''//webpages.charter.net/yospiff/Images/Smileys/WooHoo2.gif'', ''/'') + 1) . ''" border="0" src="//webpages.charter.net/yospiff/Images/Smileys/WooHoo2.gif"/> <br/> <br/>Well done on your first ribbon for the year, and with an awesome shot! 20 mins before deadline, wow, that was impressive!<br/><br/><i>Message edited by author 2013-02-08 00:39:30.</i></td>', '  Well done on your first ribbon for the year, and with an awesome shot! 20 mins before deadline, wow, that was impressive!', '2013-02-08 00:21:54.000000', '2013-02-08 00:39:30.000000', 0),
